        "background": "南朝梁武帝时期（502-549年），吴均任吴兴郡主簿时作。时值\\\"竟陵八友\\\"文学集团活跃，山水文学兴起。富春江作为隐逸文化象征，吸引文人雅集。信中\\\"朱元思\\\"应为虚构人物，实为山水审美宣言。",
