        "background": "战国中期（约公元前300年），孟子周游列国宣扬仁政学说。时值诸侯混战，孟子针对当时国君迷信武力的现象，提出\\\"人和\\\"高于\\\"天时地利\\\"的战争观。",
        "analysis": "文章采用层进式论证：先否定\\\"天时→地利\\\"两种物质条件，再肯定\\\"人和\\\"的精神核心。三个\\\"不如\\\"阶梯递进，引出三个\\\"不以\\\"的政治主张。排比句气势如虹：\\\"城非不高也\\\"四句铺陈有力，\\\"得道\\\"\\\"失道\\\"对比鲜明，成就千古治国箴言。"
