        "display": "center",
        "content": [
            {
                "line": "丙辰中秋，欢饮达旦，大醉，作此篇，兼怀子由。",
                "trans": "明月几时有？把酒问青天。",
                "pinyin": "转朱阁，低绮户，照无眠。"
            }
        ],
        "background": "丙辰年中秋，畅饮到天亮，大醉而作此词，兼怀弟弟子由。",
        "analysis": "明月何时出现？举杯问青天。\n不知天上宫殿，今夜是哪年。\n我想乘风归去，又怕琼玉楼阁，高处太清寒。\n月下起舞清影随，何似在人间。\n月转朱红楼阁，低照雕花门窗，照着不眠人。\n月儿不该有怨恨，为何总在离别时圆？\n人有悲欢离合，月有阴晴圆缺，此事自古难周全。\n唯愿人长久安康，千里共享明月光。\nbǐng chén zhōng qiū huān yǐn dá dàn dà zuì zuò cǐ piān jiān huái zǐ yóu\nmíng yuè jǐ shí yǒu bǎ jiǔ wèn qīng tiān\nbù zhī tiān shàng gōng què jīn xī shì hé nián\nwǒ yù chéng fēng guī qù yòu kǒng qióng lóu yù yǔ gāo chù bù shèng hán\nqǐ wǔ nòng qīng yǐng hé sì zài rén jiān\nzhuǎn zhū gé dī qǐ hù zhào wú mián\nbù yīng yǒu hèn hé shì cháng xiàng bié shí yuán\nrén yǒu bēi huān lí hé yuè yǒu yīn qíng yuán quē cǐ shì gǔ nán quán\ndàn yuàn rén cháng jiǔ qiān lǐ gòng chán juān\n熙宁九年(1076)中秋，苏轼任密州知州。时值王安石变法期间，苏轼因政见不合自请外放，已七年未见胞弟苏辙。中秋夜对月畅饮，于醉中抒写人生感悟。\n上阕\\\"问月\\\"开启哲思，\\\"归去\\\"与\\\"人间\\\"的矛盾反映出世与出世的挣扎。下阕\\\"转朱阁\\\"三句勾勒月光移动轨迹，\\\"不应有恨\\\"的反问推进情感张力。结尾\\\"悲欢离合\\\"的宇宙观照与\\\"千里共婵娟\\\"的美好祝愿，使个人情怀升华为人类共通情感。全词将诗情、画意、哲理熔铸为咏月绝唱。"
