        "background": "此诗约作于唐文宗开成三年（838年）。李商隐青年时在玉阳山学道，与女道士宋华阳相恋，但受唐代道教戒律与世俗礼法约束，感情隐秘难言。另说为向权贵令狐绹陈情而作，寄寓仕途困顿之悲。诗中\\\"蓬山\\\"或暗指令狐绹府邸，\\\"青鸟\\\"喻沟通媒介。",
        "analysis": "本诗以\\\"双难\\\"结构开篇，首句两用\\\"难\\\"字形成情感张力：前指相会不易，后言离别煎熬。\\\"东风无力\\\"既写暮春实景，又喻爱情在世俗压力下凋零。颔联\\\"春蚕\\\"\\\"蜡炬\\\"以生命意象构建双重隐喻：\\\"丝\\\"谐音\\\"思\\\"，喻至死不渝的思念；\\\"泪\\\"兼指蜡油与眼泪，表痛苦永恒。颈联空间转换，\\\"晓镜\\\"写己容憔悴，\\\"夜吟\\\"拟对方孤寒，月光之\\\"寒\\\"实为心理投射。尾联借蓬莱仙山、青鸟信使的缥缈意象，在绝望中寄寓微茫希望，呼应\\\"难\\\"字循环。清代赵臣瑗评：\\\"言情至此，真可以惊天地而泣鬼神\\\"（《山满楼笺注》）。全诗七律结构精密：首联破题定调，颔联立骨塑魂，颈联虚实相生，尾联宕开收势。比兴手法贯穿始终，将悲剧爱情升华为永恒的生命绝唱。"
