        "background": "《送东阳马生序》是一篇典型的赠序散文，以自述体展开，语言质朴真挚，结构严谨。全文可分为三部分：开篇详述作者幼时家贫借书抄录、成年后百里求师的艰辛经历，生动刻画了“天大寒，砚冰坚”“足肤皲裂而不知”等细节，凸显其不畏困苦、专注求学的精神；中间对比当今太学生“无冻馁之患”“无奔走之劳”的优越条件，强调“非天质之卑，则心不若余之专”的论点，劝导学子珍惜机遇；结尾点明写作目的，以马生的贤能为引，表达“勉乡人以学”的志向，并驳斥可能的误解，深化主题。文章善用对比手法和具体事例，情感真挚，说理透彻，不仅展现了宋濂高尚的人格和文学造诣，更传递了勤奋、诚信、坚韧的价值观，对后世教育文学影响深远。",
