        "background": "写作背景：这首词作于辛弃疾晚年登临京口北固亭时，正值南宋偏安一隅的时期。辛弃疾一生力主抗金复国，却屡遭排挤。京口（今镇江）是军事重镇，登楼远眺，他触景生情，回忆起三国英雄事迹，以此抒发对祖国山河的热爱和对南宋朝廷苟安的不满。当时南宋朝廷软弱无能，辛弃疾借古讽今，表达了对英雄人物的向往和自身壮志未酬的感慨。",
